// Generated by AI (UnitTest MCP)
//! SQLite connection setup, migrations, and the `effective_weight` SQL function.

use rusqlite::functions::FunctionFlags;
use rusqlite::{Connection, ErrorCode};
use std::time::{Duration, Instant};

use crate::error::{MindLeakError, Result};

const SCHEMA: &str = include_str!("schema.sql");
const WAL_RETRY_DELAY: Duration = Duration::from_millis(25);
// One open (WAL mode + schema DDL + migration) can share this deadline with a
// concurrent opener of the same fresh database. 5s was enough on a dev
// machine but not on GitHub's windows-latest runner, where the maintenance
// runtime tests intermittently exhausted it applying `schema.sql`'s full DDL
// under CI-load disk contention -- reproduced consistently there, never
// locally (16x parallel, repeated runs). Widened for that headroom, not
// because the retry design itself was wrong.
const OPEN_BUSY_BUDGET: Duration = Duration::from_secs(15);
const DEFAULT_BUSY_TIMEOUT_MS: i64 = 15_000;

/// Serializes the crate's file-backed database tests against each other.
///
/// Each such test already writes to its own uniquely-named file, so they never
/// contend for the same database -- but Rust's default parallel test runner
/// still runs them (and every other test in this binary) at once, and on a
/// loaded CI runner that shared disk contention alone was enough to push a
/// normally sub-second `open` past [`OPEN_BUSY_BUDGET`], failing with
/// `Busy("migrating the schema was still locked...")`. Measured 2026-08-25 on
/// windows-latest job 97726490361: five of them failed together with that one
/// error.
///
/// Widening the budget is deliberately *not* the fix here -- that lever was
/// already pulled once (5s -> 15s, see above) and the same failure returned at
/// the higher ceiling, because per-test file isolation was never the broken
/// part. Serializing only these tests removes the contention itself and leaves
/// every in-memory test fully parallel. Mirrors the same fix already proven in
/// `mindleak-mcp`'s `maintenance::runtime` tests.
#[cfg(test)]
pub(crate) fn serialize_db_test() -> std::sync::MutexGuard<'static, ()> {
    static DB_OPENING_TEST_LOCK: std::sync::Mutex<()> = std::sync::Mutex::new(());
    DB_OPENING_TEST_LOCK
        .lock()
        .unwrap_or_else(|error| error.into_inner())
}

/// Open (or create) a MindLeak database at `path`, apply the schema, and register
/// the `effective_weight` scalar SQL function used by graph queries.
pub fn open(path: &str) -> Result<Connection> {
    let conn = Connection::open(path)?;
    configure(&conn)?;
    Ok(conn)
}

/// Open an in-memory database (used by tests and ephemeral tooling).
pub fn open_in_memory() -> Result<Connection> {
    let conn = Connection::open_in_memory()?;
    configure(&conn)?;
    Ok(conn)
}

fn configure(conn: &Connection) -> Result<()> {
    // One budget for the whole open. Many agents share one repository database,
    // so losing a lock race here is ordinary operation rather than a test
    // contrivance — but per-step budgets would add up into a wait no caller
    // asked for, which `held_lock_does_not_multiply_wal_retry_timeout` forbids.
    let deadline = Instant::now() + OPEN_BUSY_BUDGET;
    retry_while_busy(conn, deadline, "enabling WAL journal mode", || {
        conn.pragma_update(None, "journal_mode", "WAL")
            .map_err(MindLeakError::from)
    })?;
    conn.pragma_update(None, "foreign_keys", "ON")?;
    retry_while_busy(conn, deadline, "applying the schema", || {
        conn.execute_batch(SCHEMA).map_err(MindLeakError::from)
    })?;
    // Safe to re-run: every migration step is conditional, and a busy attempt
    // rolls its transaction back before returning.
    let rebuilt = retry_while_busy(conn, deadline, "migrating the schema", || migrate(conn))?;
    if rebuilt {
        reclaim_free_pages(conn);
    }
    register_functions(conn)?;
    Ok(())
}

/// Return the pages a table rebuild freed to the filesystem.
///
/// A rebuild leaves the old table's pages on the freelist, so a migration that
/// *shrinks* the data still grows the file. Measured on a 421.5 MiB copy of a
/// real graph, the embeddings rebuild produced a file 61.9% free pages; this
/// takes it to 228.1 MiB. Without it the fix that discards 142 MiB of orphans
/// hands back a file 39% larger than it found, and only a manual VACUUM would
/// ever undo that.
///
/// The rebuild and this vacuum together add about 11 seconds to the one open
/// that migrates, against an `OPEN_BUSY_BUDGET` of 15 — enough headroom on a
/// graph this size, and not enough to assume on a much larger one. Do not widen
/// that budget to buy more: it went 5s to 15s once already for a different
/// cause, and a peer that exhausts it gets a named error and succeeds on its
/// next open, because by then the migration is done.
///
/// Best-effort by design, and outside `migrate`'s transaction because VACUUM
/// cannot run inside one. The rows are already correct by this point and the
/// space stays reclaimable, so losing a lock race to another process sharing
/// this database is not a reason to fail an open.
fn reclaim_free_pages(conn: &Connection) {
    if let Err(error) = conn.execute_batch("VACUUM") {
        tracing::warn!(
            target: "mindleak::db",
            %error,
            "could not reclaim free pages after migrating; the data is correct and the space stays reclaimable"
        );
    }
}

/// Retry `operation` while SQLite reports the database busy, until `deadline`.
///
/// `busy_timeout` covers waits inside a statement, but not every step honours
/// it — `PRAGMA journal_mode = WAL` needs an exclusive lock and can refuse
/// outright, which is why this retry existed for that call alone. The failure it
/// produced named neither the step nor the cause, so a CI log said only
/// "database is locked" and the next reader had to rediscover all of this.
///
/// Each attempt is given only the budget that remains. Checking the deadline
/// between attempts is not enough: SQLite's own wait is not bounded by ours, so
/// an attempt starting just before the deadline could block a further full
/// timeout and overshoot by that much — the very multiplication
/// `held_lock_does_not_multiply_wal_retry_timeout` exists to forbid.
fn retry_while_busy<T>(
    conn: &Connection,
    deadline: Instant,
    step: &'static str,
    mut operation: impl FnMut() -> Result<T>,
) -> Result<T> {
    loop {
        let remaining = deadline.saturating_duration_since(Instant::now());
        if remaining.is_zero() {
            return Err(busy_step(step));
        }
        conn.pragma_update(None, "busy_timeout", remaining.as_millis() as i64)?;
        match operation() {
            Ok(value) => {
                conn.pragma_update(None, "busy_timeout", DEFAULT_BUSY_TIMEOUT_MS)?;
                return Ok(value);
            }
            Err(error) if is_busy_error(&error) => {
                if Instant::now() >= deadline {
                    return Err(busy_step(step));
                }
                std::thread::sleep(WAL_RETRY_DELAY);
            }
            Err(error) => return Err(error),
        }
    }
}

fn busy_step(step: &'static str) -> MindLeakError {
    MindLeakError::Busy(format!(
        "{step} was still locked after {}s; another process is opening or \
         migrating this database",
        OPEN_BUSY_BUDGET.as_secs()
    ))
}

fn is_busy_error(error: &MindLeakError) -> bool {
    matches!(error, MindLeakError::Sqlite(error) if is_busy(error))
}

fn is_busy(error: &rusqlite::Error) -> bool {
    matches!(
        error,
        rusqlite::Error::SqliteFailure(code, _)
            if matches!(code.code, ErrorCode::DatabaseBusy | ErrorCode::DatabaseLocked)
    )
}

/// Register `effective_weight(base, half_life_hours, updated_at, now)` so the
/// decay formula can run inside SQL (filtering/ordering) without SQLite math
/// extensions.
fn register_functions(conn: &Connection) -> Result<()> {
    conn.create_scalar_function(
        "effective_weight",
        4,
        FunctionFlags::SQLITE_UTF8 | FunctionFlags::SQLITE_DETERMINISTIC,
        |ctx| {
            let base: f64 = ctx.get(0)?;
            let half_life: f64 = ctx.get(1)?;
            let updated_at: i64 = ctx.get(2)?;
            let now: i64 = ctx.get(3)?;
            Ok(crate::decay::effective_weight(
                base, half_life, updated_at, now,
            ))
        },
    )?;
    Ok(())
}

/// Idempotently add columns to a pre-existing `edges` table (fresh databases
/// already have them from the schema). Backfills signal span and unambiguous
/// structural ownership without trying to infer artifact paths from symbol ids.
fn migrate(conn: &Connection) -> Result<bool> {
    conn.execute_batch("BEGIN IMMEDIATE")?;
    let result = migrate_locked(conn);
    match result {
        Ok(rebuilt) => {
            conn.execute_batch("COMMIT")?;
            Ok(rebuilt)
        }
        Err(error) => {
            let _ = conn.execute_batch("ROLLBACK");
            Err(error)
        }
    }
}

/// Reports whether a step rebuilt a table, so the caller can reclaim its pages.
fn migrate_locked(conn: &Connection) -> Result<bool> {
    if !column_exists(conn, "edges", "first_seen")? {
        conn.execute(
            "ALTER TABLE edges ADD COLUMN first_seen INTEGER NOT NULL DEFAULT 0",
            [],
        )?;
    }
    conn.execute(
        "UPDATE edges SET first_seen = updated_at WHERE first_seen = 0",
        [],
    )?;
    if !column_exists(conn, "edges", "reinforcement_count")? {
        conn.execute(
            "ALTER TABLE edges ADD COLUMN reinforcement_count INTEGER NOT NULL DEFAULT 1",
            [],
        )?;
    }
    if !column_exists(conn, "edges", "owner_id")? {
        conn.execute("ALTER TABLE edges ADD COLUMN owner_id TEXT", [])?;
    }
    conn.execute(
        "UPDATE edges
         SET owner_id = source_id
         WHERE owner_id IS NULL AND relation = 'contains'",
        [],
    )?;
    conn.execute(
        "CREATE INDEX IF NOT EXISTS idx_edges_owner ON edges(owner_id)",
        [],
    )?;
    let rebuilt = cascade_embeddings_onto_nodes(conn)?;
    merge_forked_agent_nodes(conn)?;
    Ok(rebuilt)
}

/// Give `embeddings` the `ON DELETE CASCADE` every other child of `nodes` has.
///
/// The table is created lazily by the optional index pass, away from
/// `schema.sql` and its foreign keys, and it was written without one. Nothing
/// else swept it, so every node a prune, a re-ingest, or a snapshot replacement
/// removed left its vector behind forever. Measured on a working graph before
/// this ran: 48,502 orphaned rows, 142.1 MiB, 74.3% of the table — the leak was
/// three times larger than the data.
///
/// The tell was already in the tree. `merge_forked_agent_nodes` used to hand-
/// write a matching `DELETE FROM embeddings`, which is a cascade spelled out at
/// one call site; every other `DELETE FROM nodes` did not, and could not be
/// expected to remember. Declaring the constraint is what stops the next one
/// leaking, so that manual delete is gone rather than left beside this.
///
/// SQLite cannot add a constraint in place, so the table is rebuilt. Copying
/// only rows that still resolve is what discards the orphans — the purge is a
/// consequence of the copy, not a second statement that could disagree with it.
///
/// Reports whether it rebuilt, so the caller can reclaim the pages that freed.
fn cascade_embeddings_onto_nodes(conn: &Connection) -> Result<bool> {
    // Absent until something indexes, and `ensure_table` now builds it correctly.
    if !table_exists(conn, "embeddings")? || foreign_key_count(conn, "embeddings")? > 0 {
        return Ok(false);
    }
    // Renaming first lets `ensure_table` build the replacement, so the rebuilt
    // table is by construction the one production creates — not a second copy of
    // the definition that a later column could silently drift away from.
    //
    // Safe with foreign keys on, which a PRAGMA could not turn off here anyway
    // since this runs inside `migrate`'s transaction: nothing references
    // `embeddings`, so the rename and drop fire no cascade of their own.
    conn.execute_batch("ALTER TABLE embeddings RENAME TO embeddings_superseded;")?;
    crate::embed::ensure_table(conn)?;
    conn.execute_batch(
        "INSERT INTO embeddings (node_id, model, dim, vector, updated_at)
         SELECT e.node_id, e.model, e.dim, e.vector, e.updated_at
         FROM embeddings_superseded e JOIN nodes n ON n.id = e.node_id;
         DROP TABLE embeddings_superseded;",
    )?;
    Ok(true)
}

fn table_exists(conn: &Connection, table: &str) -> Result<bool> {
    Ok(conn.query_row(
        "SELECT EXISTS(SELECT 1 FROM sqlite_master WHERE type = 'table' AND name = ?1)",
        [table],
        |row| row.get(0),
    )?)
}

fn foreign_key_count(conn: &Connection, table: &str) -> Result<usize> {
    let mut stmt = conn.prepare(&format!("PRAGMA foreign_key_list({table})"))?;
    let mut rows = stmt.query([])?;
    let mut count = 0;
    while rows.next()?.is_some() {
        count += 1;
    }
    Ok(count)
}

/// Merge `agent:session:v1:{name}:{fingerprint}` nodes onto one identity per
/// session (ADR-0054).
///
/// The Memory Plane carries the same defect the Intent Plane did: the label in
/// the id came from the hosting server process, so one session observed under
/// two process environments produced two agent nodes. Here it is worse than a
/// miscount. `check_overlap` skips `exclude_agent` by exact id, so an agent's
/// *other half* is not excluded and it reports a collision with itself — a
/// false positive that reads exactly like a real one, telling an agent to back
/// off work nobody else is doing. `working_set` matches `source_id` exactly and
/// so returns half of its own attention.
///
/// The halves share the fingerprint, so the merge heals it. Observation edges
/// are combined rather than overwritten: the strongest weight, the latest
/// touch, the earliest first sighting, and the summed reinforcement count —
/// the same node observed twice under two names really was observed twice.
fn merge_forked_agent_nodes(conn: &Connection) -> Result<()> {
    // The canonical node: earliest creation and latest access across the halves.
    conn.execute(
        "INSERT INTO nodes (id, type, label, content, created_at, last_accessed_at)
         SELECT 'agent:session:v1:' || substr(id, -32), 'agent',
                'session:v1:' || substr(id, -32), NULL,
                min(created_at), max(last_accessed_at)
         FROM nodes
         WHERE type = 'agent' AND id GLOB 'agent:session:v1:*:*'
         GROUP BY substr(id, -32)
         ON CONFLICT(id) DO UPDATE SET
             created_at = min(created_at, excluded.created_at),
             last_accessed_at = max(last_accessed_at, excluded.last_accessed_at)",
        [],
    )?;
    // Repoint attribution onto it, folding the halves' duplicate observations.
    conn.execute(
        "INSERT INTO edges (source_id, target_id, relation, weight, half_life_hours,
                            updated_at, first_seen, reinforcement_count, owner_id)
         SELECT 'agent:session:v1:' || substr(source_id, -32), target_id, relation,
                max(weight), max(half_life_hours), max(updated_at),
                min(first_seen), sum(reinforcement_count), NULL
         FROM edges
         WHERE source_id GLOB 'agent:session:v1:*:*'
         GROUP BY substr(source_id, -32), target_id, relation
         ON CONFLICT(source_id, target_id, relation) DO UPDATE SET
             weight = max(weight, excluded.weight),
             updated_at = max(updated_at, excluded.updated_at),
             first_seen = min(first_seen, excluded.first_seen),
             reinforcement_count = reinforcement_count + excluded.reinforcement_count",
        [],
    )?;
    conn.execute(
        "DELETE FROM edges WHERE source_id GLOB 'agent:session:v1:*:*'",
        [],
    )?;
    // The `nodes_ad` trigger clears the FTS rows; the canonical id carries no
    // label segment, so it does not match the pattern and survives. The
    // embeddings of the retired halves go with them, because
    // `cascade_embeddings_onto_nodes` ran first and gave that table its cascade.
    conn.execute(
        "DELETE FROM nodes WHERE type = 'agent' AND id GLOB 'agent:session:v1:*:*'",
        [],
    )?;
    Ok(())
}

fn column_exists(conn: &Connection, table: &str, column: &str) -> Result<bool> {
    let mut stmt = conn.prepare(&format!("PRAGMA table_info({table})"))?;
    let mut rows = stmt.query([])?;
    while let Some(row) = rows.next()? {
        let name: String = row.get(1)?;
        if name == column {
            return Ok(true);
        }
    }
    Ok(false)
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::cell::Cell;
    use std::sync::{Arc, Barrier};
    use std::time::{SystemTime, UNIX_EPOCH};

    fn busy() -> MindLeakError {
        MindLeakError::Sqlite(rusqlite::Error::SqliteFailure(
            rusqlite::ffi::Error::new(5),
            Some("database is locked".into()),
        ))
    }

    /// Raw, deliberately not through `open_in_memory`, which would itself run
    /// the retry policy under test.
    fn scratch() -> Connection {
        Connection::open_in_memory().unwrap()
    }

    #[test]
    fn a_step_that_is_not_busy_runs_once_and_returns_its_value() {
        let conn = scratch();
        let attempts = Cell::new(0);

        let value = retry_while_busy(&conn, Instant::now() + OPEN_BUSY_BUDGET, "step", || {
            attempts.set(attempts.get() + 1);
            Ok(7)
        })
        .unwrap();

        assert_eq!((value, attempts.get()), (7, 1));
    }

    #[test]
    fn a_busy_step_is_retried_until_the_lock_clears() {
        let conn = scratch();
        let attempts = Cell::new(0);

        let value = retry_while_busy(&conn, Instant::now() + OPEN_BUSY_BUDGET, "step", || {
            attempts.set(attempts.get() + 1);
            if attempts.get() < 3 {
                return Err(busy());
            }
            Ok("opened")
        })
        .unwrap();

        assert_eq!((value, attempts.get()), ("opened", 3));
    }

    /// The failure this replaces said only "database is locked", so a CI log
    /// named neither which of the open steps lost the race nor that a peer
    /// process held the file.
    #[test]
    fn an_exhausted_budget_names_the_step_and_the_cause() {
        let conn = scratch();

        let error =
            retry_while_busy::<()>(
                &conn,
                Instant::now(),
                "migrating the schema",
                || Err(busy()),
            )
            .unwrap_err();

        let MindLeakError::Busy(message) = error else {
            panic!("a busy step must report Busy, not a bare sqlite passthrough: {error:?}");
        };
        assert!(
            message.contains("migrating the schema") && message.contains("another process"),
            "unhelpful busy message: {message}"
        );
    }

    /// Checking the deadline only between attempts lets one SQLite wait overrun
    /// it by a whole busy timeout, which is how a "bounded" window doubles.
    #[test]
    fn no_attempt_is_allowed_to_outlive_the_deadline() {
        let conn = scratch();
        let budget = Duration::from_millis(200);
        let started = Instant::now();

        let error =
            retry_while_busy::<()>(&conn, started + budget, "step", || Err(busy())).unwrap_err();

        assert!(matches!(error, MindLeakError::Busy(_)));
        let granted: i64 = conn
            .query_row("PRAGMA busy_timeout", [], |row| row.get(0))
            .unwrap();
        assert!(
            granted <= budget.as_millis() as i64,
            "an attempt was granted {granted}ms against a {budget:?} budget"
        );
    }

    #[test]
    fn an_error_that_is_not_busy_is_returned_without_retrying() {
        let conn = scratch();
        let attempts = Cell::new(0);

        let error =
            retry_while_busy::<()>(&conn, Instant::now() + OPEN_BUSY_BUDGET, "step", || {
                attempts.set(attempts.get() + 1);
                Err(MindLeakError::InvalidArgument("no".into()))
            })
            .unwrap_err();

        assert!(matches!(error, MindLeakError::InvalidArgument(_)));
        assert_eq!(attempts.get(), 1, "a real error must not be retried");
    }

    fn temp_db(tag: &str) -> String {
        let nanos = SystemTime::now()
            .duration_since(UNIX_EPOCH)
            .map(|duration| duration.as_nanos())
            .unwrap_or(0);
        let mut path = std::env::temp_dir();
        path.push(format!("mindleak-{tag}-{}-{nanos}.db", std::process::id()));
        path.to_string_lossy().into_owned()
    }

    fn cleanup(path: &str) {
        let _ = std::fs::remove_file(path);
        let _ = std::fs::remove_file(format!("{path}-wal"));
        let _ = std::fs::remove_file(format!("{path}-shm"));
    }

    fn create_legacy_database(path: &str) {
        let connection = Connection::open(path).unwrap();
        connection
            .execute_batch(
                "CREATE TABLE nodes (
                     id TEXT PRIMARY KEY,
                     type TEXT NOT NULL,
                     label TEXT NOT NULL,
                     content TEXT,
                     created_at INTEGER NOT NULL,
                     last_accessed_at INTEGER NOT NULL
                 );
                 CREATE TABLE edges (
                     source_id TEXT NOT NULL,
                     target_id TEXT NOT NULL,
                     relation TEXT NOT NULL,
                     weight REAL NOT NULL DEFAULT 1.0,
                     half_life_hours REAL NOT NULL DEFAULT 48.0,
                     updated_at INTEGER NOT NULL,
                     first_seen INTEGER NOT NULL DEFAULT 0,
                     PRIMARY KEY (source_id, target_id, relation)
                 );
                 INSERT INTO nodes VALUES
                     ('artifact:a', 'artifact', 'a', NULL, 10, 10),
                     ('symbol:a:f', 'symbol', 'f', NULL, 10, 10);
                 INSERT INTO edges VALUES
                     ('artifact:a', 'symbol:a:f', 'contains', 1.0, 168.0, 10, 0);",
            )
            .unwrap();
    }

    #[test]
    fn migrate_adds_edge_evidence_columns_and_backfills_contains_owner() {
        // Regression: an existing graph lacks columns from newer ADRs; normal
        // open must upgrade it in place and preserve its structural facts.
        let connection = Connection::open_in_memory().unwrap();
        connection
            .execute_batch(
                "CREATE TABLE nodes (
                     id TEXT PRIMARY KEY,
                     type TEXT NOT NULL,
                     label TEXT NOT NULL,
                     content TEXT,
                     created_at INTEGER NOT NULL,
                     last_accessed_at INTEGER NOT NULL
                 );
                 CREATE TABLE edges (
                     source_id TEXT NOT NULL,
                     target_id TEXT NOT NULL,
                     relation TEXT NOT NULL,
                     weight REAL NOT NULL DEFAULT 1.0,
                     half_life_hours REAL NOT NULL DEFAULT 48.0,
                     updated_at INTEGER NOT NULL,
                     PRIMARY KEY (source_id, target_id, relation)
                 );
                 INSERT INTO nodes VALUES
                     ('artifact:a', 'artifact', 'a', NULL, 10, 10),
                     ('symbol:a:f', 'symbol', 'f', NULL, 10, 10);
                 INSERT INTO edges VALUES
                     ('artifact:a', 'symbol:a:f', 'contains', 1.0, 168.0, 10);",
            )
            .unwrap();

        configure(&connection).unwrap();

        for column in ["first_seen", "reinforcement_count", "owner_id"] {
            assert!(column_exists(&connection, "edges", column).unwrap());
        }
        let (first_seen, reinforcement_count, owner_id): (i64, i64, Option<String>) = connection
            .query_row(
                "SELECT first_seen, reinforcement_count, owner_id FROM edges",
                [],
                |row| Ok((row.get(0)?, row.get(1)?, row.get(2)?)),
            )
            .unwrap();
        assert_eq!(first_seen, 10);
        assert_eq!(reinforcement_count, 1);
        assert_eq!(owner_id.as_deref(), Some("artifact:a"));
    }

    /// Bug: `embeddings` is created lazily by the optional index pass, away from
    /// `schema.sql`, and was written without a foreign key — so a vector
    /// outlived the node it described and nothing swept it. Measured on a
    /// working graph: 48,502 orphaned rows, 142.1 MiB, 74.3% of the table.
    ///
    /// Opening an affected database must rebuild it with the cascade and discard
    /// what already leaked, keeping every row that still resolves.
    #[test]
    fn migrate_gives_a_legacy_embeddings_table_its_cascade_and_drops_what_leaked() {
        let connection = Connection::open_in_memory().unwrap();
        connection.execute_batch(SCHEMA).unwrap();
        connection
            .execute_batch(
                "CREATE TABLE embeddings (
                     node_id    TEXT NOT NULL,
                     model      TEXT NOT NULL,
                     dim        INTEGER NOT NULL,
                     vector     BLOB NOT NULL,
                     updated_at INTEGER NOT NULL,
                     PRIMARY KEY (node_id, model)
                 );
                 INSERT INTO nodes (id, type, label, content, created_at, last_accessed_at)
                 VALUES ('artifact:live.rs', 'artifact', 'live.rs', NULL, 10, 10);
                 INSERT INTO embeddings (node_id, model, dim, vector, updated_at) VALUES
                     ('artifact:live.rs', 'nomic', 2, x'0000803f00000000', 41),
                     ('execution:already-pruned', 'nomic', 2, x'000000000000803f', 42);",
            )
            .unwrap();

        configure(&connection).unwrap();

        let rows: Vec<(String, i64, i64)> = connection
            .prepare("SELECT node_id, dim, updated_at FROM embeddings ORDER BY node_id")
            .unwrap()
            .query_map([], |row| Ok((row.get(0)?, row.get(1)?, row.get(2)?)))
            .unwrap()
            .collect::<std::result::Result<_, _>>()
            .unwrap();
        assert_eq!(
            rows,
            vec![("artifact:live.rs".to_string(), 2, 41)],
            "the orphan is discarded and the row that still resolves is carried over intact"
        );

        // Declared is not the same as enforced, so make the constraint act.
        connection
            .execute("DELETE FROM nodes WHERE id = 'artifact:live.rs'", [])
            .unwrap();
        let remaining: i64 = connection
            .query_row("SELECT count(*) FROM embeddings", [], |row| row.get(0))
            .unwrap();
        assert_eq!(remaining, 0, "the rebuilt table cascades");
    }

    /// The rebuild copies the whole table inside `migrate`'s write lock. On a
    /// real graph that is hundreds of megabytes, and `OPEN_BUSY_BUDGET` is
    /// already the constant that fails first when agents contend for this
    /// database — repeating the copy on every open would starve them all.
    #[test]
    fn the_embeddings_rebuild_does_not_repeat_on_every_open() {
        let connection = Connection::open_in_memory().unwrap();
        connection.execute_batch(SCHEMA).unwrap();
        connection
            .execute_batch(
                "CREATE TABLE embeddings (
                     node_id    TEXT NOT NULL,
                     model      TEXT NOT NULL,
                     dim        INTEGER NOT NULL,
                     vector     BLOB NOT NULL,
                     updated_at INTEGER NOT NULL,
                     PRIMARY KEY (node_id, model)
                 );",
            )
            .unwrap();
        let root_page = |conn: &Connection| -> i64 {
            conn.query_row(
                "SELECT rootpage FROM sqlite_master WHERE type = 'table' AND name = 'embeddings'",
                [],
                |row| row.get(0),
            )
            .unwrap()
        };

        configure(&connection).unwrap();
        let after_first = root_page(&connection);
        configure(&connection).unwrap();

        assert_eq!(
            after_first,
            root_page(&connection),
            "a second open rebuilt the table again; the already-constrained guard is not holding"
        );
    }

    /// Bug: rebuilding a table leaves its old pages on the freelist, so the
    /// migration that *discards* 142 MiB of orphans handed back a file larger
    /// than it found. Measured on a 410.2 MiB copy of a real graph: 569.2 MiB
    /// after the rebuild, 61.9% of it free pages, and only a manual VACUUM
    /// would ever have undone that. One VACUUM took it to 216.8 MiB in 1.4s.
    ///
    /// File-backed on purpose: an in-memory database has no file to shrink, so
    /// an in-memory version of this test would pass without the fix.
    #[test]
    fn the_rebuild_returns_the_pages_it_freed_to_the_filesystem() {
        let _serialized = serialize_db_test();
        let path = std::env::temp_dir().join(format!("mindleak-reclaim-{}.db", std::process::id()));
        let _ = std::fs::remove_file(&path);
        let connection = Connection::open(&path).unwrap();
        connection.execute_batch(SCHEMA).unwrap();
        connection
            .execute_batch(
                "CREATE TABLE embeddings (
                     node_id    TEXT NOT NULL,
                     model      TEXT NOT NULL,
                     dim        INTEGER NOT NULL,
                     vector     BLOB NOT NULL,
                     updated_at INTEGER NOT NULL,
                     PRIMARY KEY (node_id, model)
                 );
                 -- Orphaned bulk: every node_id here is absent from `nodes`.
                 WITH RECURSIVE seq(n) AS (
                     SELECT 1 UNION ALL SELECT n + 1 FROM seq WHERE n < 400
                 )
                 INSERT INTO embeddings (node_id, model, dim, vector, updated_at)
                 SELECT 'execution:pruned-' || n, 'm', 1024, zeroblob(4096), 1 FROM seq;",
            )
            .unwrap();
        let pages = |conn: &Connection| -> i64 {
            conn.query_row("PRAGMA page_count", [], |row| row.get(0))
                .unwrap()
        };
        let before = pages(&connection);

        configure(&connection).unwrap();

        let surviving: i64 = connection
            .query_row("SELECT count(*) FROM embeddings", [], |row| row.get(0))
            .unwrap();
        assert_eq!(surviving, 0, "every row was an orphan");
        let free: i64 = connection
            .query_row("PRAGMA freelist_count", [], |row| row.get(0))
            .unwrap();
        assert_eq!(free, 0, "a vacuumed database keeps no free pages");
        let after = pages(&connection);
        assert!(
            after * 2 < before,
            "the file kept the pages the rebuild freed: {before} -> {after}"
        );

        drop(connection);
        let _ = std::fs::remove_file(&path);
    }

    /// Bug: the Memory Plane carried the same forked identity the Intent Plane
    /// did (ADR-0054) — the label inside `agent:session:v1:{label}:{fp}` came
    /// from the hosting server process, so one session observed under two
    /// environments produced two agent nodes.
    ///
    /// Here it is worse than a miscount. `check_overlap` skips `exclude_agent`
    /// by exact id, so an agent's *other half* is not excluded and it reports a
    /// collision **with itself** — a false positive indistinguishable from a
    /// real one, telling an agent to back off work nobody else is doing. And
    /// `working_set` matches `source_id` exactly, so it returns half of its own
    /// attention.
    ///
    /// The merge folds the halves rather than picking one: the same artifact
    /// observed under both names really was observed twice, so the
    /// reinforcement counts add.
    #[test]
    fn migrate_merges_agent_nodes_that_forked_on_the_host_process_name() {
        let connection = Connection::open_in_memory().unwrap();
        connection.execute_batch(SCHEMA).unwrap();
        let fingerprint = "bff9bbe3968f16636cbc5522086114e3";
        connection
            .execute_batch(&format!(
                "INSERT INTO nodes (id, type, label, content, created_at, last_accessed_at) VALUES
                     ('agent:session:v1:agent:{fingerprint}', 'agent', 'session:v1:agent:{fingerprint}', NULL, 10, 40),
                     ('agent:session:v1:copilot:{fingerprint}', 'agent', 'session:v1:copilot:{fingerprint}', NULL, 20, 60),
                     ('artifact:shared.rs', 'artifact', 'shared.rs', NULL, 10, 10),
                     ('artifact:only-one-half.rs', 'artifact', 'only-one-half.rs', NULL, 10, 10);
                 INSERT INTO edges (source_id, target_id, relation, weight, half_life_hours, updated_at, first_seen, reinforcement_count) VALUES
                     ('agent:session:v1:agent:{fingerprint}', 'artifact:shared.rs', 'observed', 0.6, 48.0, 30, 10, 2),
                     ('agent:session:v1:copilot:{fingerprint}', 'artifact:shared.rs', 'observed', 0.9, 48.0, 55, 20, 3),
                     ('agent:session:v1:copilot:{fingerprint}', 'artifact:only-one-half.rs', 'observed', 0.5, 48.0, 50, 50, 1);"
            ))
            .unwrap();

        configure(&connection).unwrap();

        let canonical = format!("agent:session:v1:{fingerprint}");
        let agents: Vec<String> = connection
            .prepare("SELECT id FROM nodes WHERE type = 'agent' ORDER BY id")
            .unwrap()
            .query_map([], |row| row.get(0))
            .unwrap()
            .collect::<std::result::Result<_, _>>()
            .unwrap();
        assert_eq!(
            agents,
            vec![canonical.clone()],
            "two halves become one agent"
        );

        // The node spans both halves: earliest creation, latest activity.
        let (created, accessed): (i64, i64) = connection
            .query_row(
                "SELECT created_at, last_accessed_at FROM nodes WHERE id = ?1",
                rusqlite::params![canonical],
                |row| Ok((row.get(0)?, row.get(1)?)),
            )
            .unwrap();
        assert_eq!((created, accessed), (10, 60));

        // Both halves' observations survive, folded rather than overwritten.
        let (weight, updated, first_seen, reinforcements): (f64, i64, i64, i64) = connection
            .query_row(
                "SELECT weight, updated_at, first_seen, reinforcement_count FROM edges
                 WHERE source_id = ?1 AND target_id = 'artifact:shared.rs'",
                rusqlite::params![canonical],
                |row| Ok((row.get(0)?, row.get(1)?, row.get(2)?, row.get(3)?)),
            )
            .unwrap();
        assert_eq!(weight, 0.9, "the stronger observation wins");
        assert_eq!(updated, 55, "the later touch wins");
        assert_eq!(first_seen, 10, "the earlier sighting anchors the span");
        assert_eq!(
            reinforcements, 5,
            "2 + 3: it really was observed five times"
        );

        let owned: i64 = connection
            .query_row(
                "SELECT count(*) FROM edges WHERE source_id = ?1",
                rusqlite::params![canonical],
                |row| row.get(0),
            )
            .unwrap();
        assert_eq!(owned, 2, "the half-only observation is not dropped");

        let orphaned: i64 = connection
            .query_row(
                "SELECT count(*) FROM edges WHERE source_id GLOB 'agent:session:v1:*:*'",
                [],
                |row| row.get(0),
            )
            .unwrap();
        assert_eq!(orphaned, 0, "no attribution is left on a retired half");
    }

    #[test]
    fn concurrent_opens_serialize_legacy_migration() {
        let _serialized = serialize_db_test();
        let path = temp_db("concurrent-migration");
        create_legacy_database(&path);
        let barrier = Arc::new(Barrier::new(3));
        let mut handles = Vec::new();
        for _ in 0..2 {
            let path = path.clone();
            let barrier = Arc::clone(&barrier);
            handles.push(std::thread::spawn(move || {
                barrier.wait();
                open(&path)
            }));
        }
        barrier.wait();

        for handle in handles {
            let result = handle.join().unwrap();
            assert!(result.is_ok(), "concurrent open failed: {result:?}");
        }
        let connection = open(&path).unwrap();
        let (first_seen, owner_id): (i64, Option<String>) = connection
            .query_row("SELECT first_seen, owner_id FROM edges", [], |row| {
                Ok((row.get(0)?, row.get(1)?))
            })
            .unwrap();
        assert_eq!(first_seen, 10);
        assert_eq!(owner_id.as_deref(), Some("artifact:a"));
        drop(connection);
        cleanup(&path);
    }

    #[test]
    fn held_lock_does_not_multiply_wal_retry_timeout() {
        let _serialized = serialize_db_test();
        let path = temp_db("bounded-wal-retry");
        create_legacy_database(&path);
        let holder = Connection::open(&path).unwrap();
        holder.execute_batch("BEGIN EXCLUSIVE").unwrap();

        let started = Instant::now();
        let result = open(&path);
        let elapsed = started.elapsed();

        assert!(result.is_err());
        // Bounded by roughly 2x the budget (one step can start just before the
        // deadline and still run a full further wait), plus slack for a slow
        // CI disk -- scaled from the constant so widening OPEN_BUSY_BUDGET can
        // never silently leave this assertion looser or tighter than intended.
        let ceiling = OPEN_BUSY_BUDGET * 3;
        assert!(
            elapsed < ceiling,
            "open exceeded bounded retry window: {elapsed:?} (ceiling {ceiling:?})"
        );
        holder.execute_batch("ROLLBACK").unwrap();
        cleanup(&path);
    }
}
